import { createContext, useContext, useEffect, useState } from 'react';
import {
  getCart,
  addToCart,
  removeFromCart
} from '../services/cartService';

const CartContext = createContext();

export const CartProvider = ({ children }) => {
  const [cartMap, setCartMap] = useState(new Map());
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    loadCart();
  }, []);

  const loadCart = async () => {
    try {
      const items = await getCart();
      const map = new Map();
      items.forEach(item => {
        map.set(item.tour.id, item);
      });
      setCartMap(map);
    } catch (e) {
      console.error('Ошибка загрузки корзины', e);
    } finally {
      setLoading(false);
    }
  };

  const toggleCart = async (tourId) => {
    if (cartMap.has(tourId)) {
      const item = cartMap.get(tourId);
      await removeFromCart(item.id);

      setCartMap(prev => {
        const copy = new Map(prev);
        copy.delete(tourId);
        return copy;
      });
    } else {
      await addToCart(tourId, 1);

      await loadCart(); // проще и безопаснее
    }
  };

  return (
    <CartContext.Provider
      value={{
        cartMap,
        cartIds: new Set(cartMap.keys()),
        toggleCart,
        loading
      }}
    >
      {children}
    </CartContext.Provider>
  );
};

export const useCart = () => useContext(CartContext);
